do $$ begin
  assert (select relrowsecurity from pg_class where oid = 'public.establishment_sites'::regclass), 'RLS enabled';
  assert not has_table_privilege('anon', 'public.establishment_sites', 'SELECT'), 'anonymous table reads denied';
  assert not has_column_privilege('authenticated', 'public.establishment_sites', 'presence_enabled', 'UPDATE'), 'owner cannot grant entitlement';
  assert not has_column_privilege('authenticated', 'public.establishment_sites', 'presence_enabled', 'INSERT'), 'owner cannot insert entitlement';
  assert not has_table_privilege('authenticated', 'public.establishment_sites', 'DELETE'), 'owner cannot delete';
  assert not has_function_privilege('public', 'public.get_public_establishment_site(text)', 'EXECUTE'), 'RPC not executable by PUBLIC';
  assert has_function_privilege('anon', 'public.get_public_establishment_site(text)', 'EXECUTE'), 'public RPC available';
  assert not has_function_privilege('public', 'public.list_published_site_slugs()', 'EXECUTE'), 'sitemap RPC not executable by PUBLIC';
  assert has_function_privilege('anon', 'public.list_published_site_slugs()', 'EXECUTE'), 'sitemap RPC available';
  assert public.is_reserved_site_slug('admin'), 'admin slug reserved';
  assert public.is_reserved_site_slug('app'), 'app slug reserved';
  assert public.is_reserved_site_slug('www'), 'www slug reserved';
  assert public.is_reserved_site_slug('blog'), 'blog slug reserved';
  assert not public.is_safe_site_asset_url('https://evil.example.com/photo.jpg'), 'external url blocked';
  assert public.is_safe_site_asset_url('https://lcqwrngscsziysyfhpfj.supabase.co/storage/v1/object/public/logos/owner-a/presenca-logo-1.webp'), 'supabase storage logo allowed';
  assert not has_function_privilege('public', 'public.is_safe_google_maps_url(text)', 'EXECUTE'), 'maps validator not executable by PUBLIC';
  assert has_function_privilege('anon', 'public.is_safe_google_maps_url(text)', 'EXECUTE'), 'maps validator available';
  assert public.is_safe_google_maps_url('https://www.google.com/maps/place/Rua+X/@-23.5,-46.6,17z'), 'google maps place allowed';
  assert public.is_safe_google_maps_url('https://www.google.com.br/maps?q=-23.5,-46.6'), 'google.com.br maps allowed';
  assert public.is_safe_google_maps_url('https://maps.google.com/?q=38.7,-9.1'), 'maps.google.com allowed';
  assert public.is_safe_google_maps_url('https://maps.app.goo.gl/Abc123'), 'short link allowed';
  assert public.is_safe_google_maps_url('https://goo.gl/maps/Abc123'), 'legacy short link allowed';
  assert not public.is_safe_google_maps_url(null), 'null blocked';
  assert not public.is_safe_google_maps_url('javascript:alert(1)'), 'javascript blocked';
  assert not public.is_safe_google_maps_url('http://www.google.com/maps'), 'http blocked';
  assert not public.is_safe_google_maps_url('https://evil.example.com/maps'), 'external host blocked';
  assert not public.is_safe_google_maps_url('https://www.google.com.evil.com/maps'), 'lookalike host blocked';
  assert not public.is_safe_google_maps_url('https://www.google.com@evil.com/maps'), 'userinfo trick blocked';
  assert not public.is_safe_google_maps_url('https://user:pass@www.google.com/maps'), 'credentials blocked';
  assert not public.is_safe_google_maps_url('https://www.google.com:8443/maps'), 'port blocked';
  assert not public.is_safe_google_maps_url('https://www.google.com/search?q=maps'), 'non-maps path blocked';
  assert not public.is_safe_google_maps_url('https://www.google.com/mapsfoo'), 'path prefix trick blocked';
  assert not public.is_safe_google_maps_url('https://maps.app.goo.gl/'), 'empty short link blocked';
  assert not public.is_safe_google_maps_url('https://goo.gl/maps/?q=1'), 'empty legacy short link with query blocked';
  assert not public.is_safe_google_maps_url('https://www.google.com/maps/../url?q=https://evil.com'), 'dot-segment redirect blocked';
  assert not public.is_safe_google_maps_url('https://www.google.com/maps/%2e%2e/url?q=https://evil.com'), 'encoded dot-segment redirect blocked';
  assert not public.is_safe_google_maps_url('https://goo.gl/maps/%2E%2E/EvilHash'), 'encoded short link dot-segment blocked';
  assert not public.is_safe_google_maps_url('https://maps.app.goo.gl/%2e'), 'encoded single dot-segment blocked';
  assert not public.is_safe_google_maps_url('https://goo.gl/maps/../EvilHash'), 'short link dot-segment blocked';
  assert not public.is_safe_google_maps_url('https://maps.app.goo.gl/./'), 'single dot-segment blocked';
  assert not public.is_safe_google_maps_url('<iframe src="https://www.google.com/maps"></iframe>'), 'markup blocked';
  assert not public.is_safe_google_maps_url('https://www.google.com/maps/a b'), 'whitespace blocked';
  assert not public.is_safe_google_maps_url('https://www.google.com/maps/' || chr(160) || 'x'), 'nbsp blocked';
  assert not public.is_safe_google_maps_url('https://www.google.com/maps/' || repeat('a', 600)), 'too long blocked';
end $$;
